import React, { useState, useEffect, useRef, useMemo, useCallback, useReducer, createContext, useContext, Component } from 'react';

function App() {
  const [todos, setTodos] = useState([]);
  const [text, setText] = useState('');

  const add = () => {
    const t = text.trim();
    if (!t) return;
    setTodos([...todos, { id: Date.now() + Math.random(), text: t, done: false }]);
    setText('');
  };

  // Add toggle and remove functions

  return (
    <div>
      <input
        id="new-todo"
        value={text}
        onChange={(e) => setText(e.target.value)}
        placeholder="What needs doing?"
      />
      <button id="add" onClick={add}>Add</button>
      <ul id="todos">
        {todos.map((todo) => (
          <li key={todo.id}>{todo.text}</li>
        ))}
      </ul>
    </div>
  );
}

export default App;

