import { describe, test, expect } from 'vitest';
import { render, fireEvent, waitFor } from '@testing-library/react';
import '@testing-library/jest-dom';
import React from 'react';
import App from '../src/App';

const tick = (ms = 20) => new Promise((resolve) => setTimeout(resolve, ms));

describe('Toggle & Delete', () => {
  test('Toggling a todo adds the "done" class to its <li>', async () => {
    const { container: root } = render(<App />);
    const input = root.querySelector('#new-todo');
const add = root.querySelector('#add');
const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
setter.call(input, 'Buy milk');
input.dispatchEvent(new Event('input', { bubbles: true }));
await tick();
add.click();
await tick();
const toggle = root.querySelector('#todos li .toggle');
if (!toggle) throw new Error('Missing .toggle checkbox in todo item');
toggle.click();
await tick();
const li = root.querySelector('#todos li');
if (!li.className.includes('done')) throw new Error('Toggled todo should have class "done"');
toggle.click();
await tick();
if (root.querySelector('#todos li').className.includes('done'))
  throw new Error('Toggling again should remove the "done" class');
  });

  test('Delete button removes only its own todo', async () => {
    const { container: root } = render(<App />);
    const input = root.querySelector('#new-todo');
const add = root.querySelector('#add');
const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
setter.call(input, 'Second');
input.dispatchEvent(new Event('input', { bubbles: true }));
await tick();
add.click();
await tick();
const before = root.querySelectorAll('#todos li').length;
const firstDelete = root.querySelector('#todos li .delete');
if (!firstDelete) throw new Error('Missing .delete button in todo item');
firstDelete.click();
await tick();
const after = root.querySelectorAll('#todos li').length;
if (after !== before - 1)
  throw new Error('Delete should remove exactly one todo (was ' + before + ', now ' + after + ')');
  });
});
